// src/pages/Profile.js

import { FiSettings } from "react-icons/fi";
import { useNavigate } from "react-router-dom";

const books = [
  { title: "노르웨이의 숲", review: "상실 이후에도 사람은 계속 살아간다는 점이 가장 인상 깊었다." },
  { title: "데미안", review: "자기 자신을 찾아가는 과정이 정말 인상 깊었다." },
  { title: "어린왕자", review: "어른이 된다는 건 무엇일까 다시 생각하게 만든 책이었다." },
  { title: "1984", review: "감시 사회의 무서움을 현실적으로 보여줘서 몰입감이 강했다." },
  { title: "해변의 카프카", review: "현실과 환상이 섞이는 분위기가 매력적이었다." },
  { title: "채식주의자", review: "인물의 심리 변화가 굉장히 강렬했다." },
];

function Profile() {
  const navigate = useNavigate();

  const currentUser = JSON.parse(localStorage.getItem("currentUser"));
  const userName = currentUser?.name || "READLY";
  const totalHeight = books.length * 2;

  return (
    <div className="page">
      {/* 상단 */}
      <div className="profile-header">
        <div className="logo">READLY</div>
        <FiSettings className="setting-icon" />
      </div>

      {/* 프로필 */}
      <div className="profile-top">
        <div className="profile-image"></div>
        <div className="profile-info">
          <div className="profile-name">{userName} ✏️</div>
          <div className="follow-wrap">
            <div className="follow-box">
              <div className="follow-num">100</div>
              <div className="follow-text">팔로워</div>
            </div>
            <div className="follow-box">
              <div className="follow-num">100</div>
              <div className="follow-text">팔로잉</div>
            </div>
          </div>
        </div>
      </div>

      {/* 소개 */}
      <div className="profile-desc">
        에세이를 좋아하는 책린이 입니다!
        <br />
        instagram: xx_123
      </div>

      <div className="line"></div>

      {/* 책장 */}
      {/* 책장 */}
      <div className="books-section">
        <div style={{ fontSize: "14px", color: "#888", marginBottom: "16px" }}>
          현재 {totalHeight}cm만큼 쌓였어요! 조금 더 분발해요!
        </div>

        <div style={{ position: "relative" }}>
          <div
            style={{
              display: "flex",
              alignItems: "flex-end",
              gap: "0px",
              overflowX: "auto",
              overflowY: "hidden",
              padding: "20px 0 0px",
            }}
          >
            {books.map((book, index) => {
              const heights = [180, 220, 160, 200, 175, 215, 165, 190];
              const colors = [
                "#7bc142", "#a8d84e", "#5aab35", "#c5e87a",
                "#68b83e", "#b2de5f", "#4e9e2f", "#d4f09a",
              ];
              const h = heights[index % heights.length];
              const bg = colors[index % colors.length];

              return (
                <div
                  key={index}
                  style={{ flexShrink: 0, cursor: "pointer" }}
                  onClick={() =>
                    navigate("/review", {
                      state: { title: book.title, review: book.review },
                    })
                  }
                >
                  <div
                    style={{
                      width: "48px",
                      height: `${h}px`,
                      background: bg,
                      borderRadius: "6px 6px 0 0",
                      display: "flex",
                      justifyContent: "center",
                      alignItems: "center",
                      color: "rgba(0,0,0,0.25)",
                      fontSize: "11px",
                      fontWeight: "700",
                      writingMode: "vertical-rl",
                      textOrientation: "mixed",
                      overflow: "hidden",
                      padding: "10px 0",
                    }}
                  >
                    {book.title}
                  </div>
                </div>
              );
            })}
          </div>

          {/* 책장 바닥 */}
          <div
            style={{
              height: "12px",
              background: "#8ab84a",
              borderRadius: "0 0 6px 6px",
            }}
          />
        </div>
      </div>
    </div>
  );
}

export default Profile;
